      body.innerHTML = '<main class="onepage">' +
        '<section style="' + heroStyle + 'padding:48px 52px 0;display:flex;flex-direction:column;position:relative;overflow:hidden">' +
        '<div style="display:flex;align-items:center;gap:12px;' + disp(20) + '">' + logoImg(HERO, '', 'width:44px;height:44px;object-fit:contain;' + tileStyle(HERO)) + esc(NAME) + '</div>' +
        '<div style="margin-top:auto;' + disp(64, .95) + '">Our brand<br>on one page</div><p style="font-size:17px;opacity:.85;max-width:44ch;margin:16px 0 28px">' + fmt((DS.identity && DS.identity.positioning) || '') + '</p>' +
        '<div style="display:flex;height:' + (QUIET ? 12 : 70) + 'px;margin:0 -52px">' + ['--ds-accent'].concat(palette).map((t) => '<span style="flex:1;background:var(' + t + ')"></span>').join('') + '</div></section>' +
        '<section style="padding:30px 52px;display:grid;grid-template-columns:1fr 1fr;gap:18px 30px;align-content:start">' +
        '<div><div class="label muted">Colour</div><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-top:10px">' + ['--ds-brand', '--ds-accent', '--ds-ink', '--ds-canvas'].concat(palette).slice(0, 8).map((t) => '<div style="height:52px;border-radius:10px;background:var(' + t + ');box-shadow:inset 0 0 0 1px var(--ds-line);color:' + on(t) + ';font:500 9px var(--ds-font-label);padding:6px;display:flex;align-items:flex-end">' + hex(t) + '</div>').join('') + '</div></div>' +
        '<div><div class="label muted">Type</div>' + (DS.type || []).map((f) => '<div style="font-family:var(' + f.token + ');font-size:21px;margin-top:8px">' + esc(f.family) + ' <span class="muted" style="font:400 12px var(--ds-font-body)">' + esc(f.role) + '</span></div>').join('') + '</div>' +
        '<div><div class="label muted">Logo</div><div style="display:flex;gap:14px;align-items:center;margin-top:10px"><img src="' + esc(logoSrc) + '" alt="" style="width:60px;height:60px;object-fit:contain"><div style="font-size:12.5px">' + list(((DS.logo && DS.logo.rules) || []).slice(0, 3)) + '</div></div></div>' +
        '<div><div class="label muted">Buttons</div><div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap"><span class="ds-btn ds-btn--accent ds-btn--sm">' + esc(C.primaryAction || 'Get started') + '</span><span class="ds-btn ds-btn--ghost ds-btn--sm">' + esc(C.secondaryAction || 'Learn more') + '</span></div></div>' +
        '<div style="grid-column:1/-1;background:var(--ds-surface);border-radius:18px;padding:18px 22px"><div class="label muted">Voice</div><div style="' + disp(24, 1.15) + 'margin:8px 0 10px">' + fmt(V.oneLine || '') + '</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;font-size:12.5px"><div class="do"><b class="label">We are</b>' + list((V.weAre || []).slice(0, 3).map((r) => r[0])) + '</div><div class="dont"><b class="label">We are not</b>' + list((V.weAre || []).slice(0, 3).map((r) => r[1])) + '</div></div></div>' +
        '<div style="grid-column:1/-1;display:flex;justify-content:space-between" class="label muted"><span>' + esc(M.domain || '') + '</span><span>Version ' + esc(M.version || '1.0') + '</span></div>' +
        '</section></main>';
